import { CalendarClock, GripVertical } from '@gntik-ai/icons';
import { Avatar, Badge, cn, Timestamp } from '@gntik-ai/ui';
import type { DragEvent, KeyboardEvent } from 'react';
import { priorityLabels, priorityTones, type BoardCard, type BoardColumn } from './data';

export interface LaneProps {
  column: BoardColumn;
  cards: BoardCard[];
  headingId: string;
  instructionsId: string;
  grabbedId: string | null;
  draggingId: string | null;
  isDropTarget: boolean;
  register: (id: string) => (el: HTMLButtonElement | null) => void;
  onOpen: (id: string) => void;
  onCardKeyDown: (id: string) => (e: KeyboardEvent<HTMLButtonElement>) => void;
  onCardKeyUp: (e: KeyboardEvent<HTMLButtonElement>) => void;
  onDragStart: (id: string) => (e: DragEvent<HTMLElement>) => void;
  onDragEnd: () => void;
  onDragOver: (e: DragEvent<HTMLElement>) => void;
  onDrop: (e: DragEvent<HTMLElement>) => void;
}

/** One board column: heading with count and a list of draggable card buttons. */
export function Lane({
  column,
  cards,
  headingId,
  instructionsId,
  grabbedId,
  draggingId,
  isDropTarget,
  register,
  onOpen,
  onCardKeyDown,
  onCardKeyUp,
  onDragStart,
  onDragEnd,
  onDragOver,
  onDrop,
}: LaneProps) {
  return (
    <section
      aria-labelledby={headingId}
      onDragOver={onDragOver}
      onDrop={onDrop}
      data-drop-target={isDropTarget || undefined}
      className="flex w-72 shrink-0 flex-col rounded-xl border border-border bg-secondary/40 data-[drop-target]:border-primary/60 data-[drop-target]:bg-accent/40"
    >
      <h2 id={headingId} className="flex items-center gap-2 px-3.5 pt-3 pb-2 text-[13px] font-semibold text-foreground">
        {column.title}
        <span className="font-mono text-[11px] font-normal text-muted-foreground">
          {cards.length}
          <span className="sr-only"> cards</span>
        </span>
      </h2>
      <ul className="flex min-h-24 flex-1 flex-col gap-2 px-2 pb-2">
        {cards.map((card, index) => (
          <li key={card.id} data-card-index={index}>
            <button
              ref={register(card.id)}
              type="button"
              draggable
              aria-describedby={instructionsId}
              aria-pressed={grabbedId === card.id}
              onClick={() => onOpen(card.id)}
              onKeyDown={onCardKeyDown(card.id)}
              onKeyUp={onCardKeyUp}
              onDragStart={onDragStart(card.id)}
              onDragEnd={onDragEnd}
              className={cn(
                'group flex w-full cursor-grab flex-col gap-2 rounded-lg border border-border bg-card p-3 text-start shadow-sm transition-colors motion-reduce:transition-none hover:border-primary/40 focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-focus-ring',
                'aria-pressed:border-primary aria-pressed:bg-accent',
                draggingId === card.id && 'opacity-50',
              )}
            >
              <span className="flex items-start gap-2">
                <span className="min-w-0 flex-1 text-[13px] leading-snug font-medium text-foreground">{card.title}</span>
                <GripVertical size={14} aria-hidden className="mt-0.5 shrink-0 text-muted-foreground" />
              </span>
              <span className="flex flex-wrap items-center gap-1.5">
                <span className="font-mono text-[11px] text-muted-foreground">{card.id}</span>
                <Badge size="sm" tone={priorityTones[card.priority]}>
                  {priorityLabels[card.priority]}
                </Badge>
                {card.labels.map((l) => (
                  <Badge key={l} size="sm" variant="outline">
                    {l}
                  </Badge>
                ))}
              </span>
              <span className="flex items-center justify-between gap-2 text-[11.5px] text-muted-foreground">
                <span className="inline-flex items-center gap-1">
                  {card.due && (
                    <>
                      <CalendarClock size={12} aria-hidden />
                      <span className="sr-only">Due </span>
                      <Timestamp value={card.due} format="absolute" tooltip={false} dateOptions={{ month: 'short', day: 'numeric' }} />
                    </>
                  )}
                </span>
                <Avatar size="xs" name={card.assignee} />
              </span>
            </button>
          </li>
        ))}
      </ul>
    </section>
  );
}

import { PageHeader } from '@gntik-ai/blocks';
import { Plus } from '@gntik-ai/icons';
import {
  Avatar,
  Badge,
  Drawer,
  DrawerBody,
  DrawerContent,
  DrawerDescription,
  DrawerHeader,
  DrawerTitle,
  HStack,
  Page,
  SimpleSelect,
  Stack,
  Text,
  Timestamp,
  VisuallyHidden,
  type BreadcrumbItem,
} from '@gntik-ai/ui';
import { useId, useState } from 'react';
import { ConsoleShell, type ConsoleShellProps } from '../shared/ConsoleShell';
import { boardBreadcrumbs, boardCards, boardColumns, boardState, locate, priorityLabels, priorityTones, type BoardCard, type BoardColumn, type BoardState } from './data';
import { Lane } from './Lane';
import { useBoard } from './useBoard';

export interface BoardProps {
  title: string;
  description: string;
  columns: BoardColumn[];
  cards: BoardCard[];
  /** Card ids per column id. */
  defaultState: BoardState;
  /** Fires after a drop (pointer, keyboard or the detail drawer's status select). */
  onMove: (cardId: string, toColumn: string, toIndex: number) => void;
  onCreate: () => void;
  breadcrumbs: BreadcrumbItem[];
  currentHref: string;
  shell: Omit<ConsoleShellProps, 'children'>;
}

/** Kanban board: columns with pointer and keyboard drag-and-drop, live announcements and a card detail Drawer. */
export default function BoardPage(props: Partial<BoardProps>) {
  const {
    title = 'Sprint board',
    description = 'Drag cards between columns, or focus a card and press Space to pick it up.',
    columns = boardColumns,
    cards = boardCards,
    defaultState = boardState,
    onMove,
    onCreate,
    breadcrumbs = boardBreadcrumbs,
    currentHref = '/projects',
    shell,
  } = props;
  const board = useBoard({ columns, cards, initial: defaultState, onMove });
  const [openId, setOpenId] = useState<string | null>(null);
  const ids = useId();
  const byId = new Map(cards.map((c) => [c.id, c]));
  const open = openId ? byId.get(openId) : undefined;
  const openAt = openId ? locate(board.state, openId) : null;

  return (
    <ConsoleShell breadcrumbs={breadcrumbs} currentHref={currentHref} {...shell}>
      <Page
        width="full"
        header={
          <PageHeader breadcrumbs={null} title={title} description={description} status="" meta={[]} tabs={null} actions={[{ label: 'New card', icon: Plus, onClick: onCreate }]} />
        }
      >
        <VisuallyHidden id={`${ids}-help`}>Press Space to pick up the card, arrow keys to move it, Space to drop and Escape to cancel. Enter opens the details.</VisuallyHidden>
        <VisuallyHidden aria-live="assertive" aria-atomic="true">
          {board.announcement}
        </VisuallyHidden>
        <div role="group" aria-label="Board" className="flex gap-4 overflow-x-auto pb-2">
          {columns.map((col) => (
            <Lane
              key={col.id}
              column={col}
              cards={(board.state[col.id] ?? []).flatMap((id) => byId.get(id) ?? [])}
              headingId={`${ids}-${col.id}`}
              instructionsId={`${ids}-help`}
              grabbedId={board.grabbedId}
              draggingId={board.dragging}
              isDropTarget={board.dropColumn === col.id}
              register={board.register}
              onOpen={setOpenId}
              onCardKeyDown={board.onCardKeyDown}
              onCardKeyUp={board.onCardKeyUp}
              onDragStart={board.onDragStart}
              onDragEnd={board.onDragEnd}
              onDragOver={board.onColumnDragOver(col.id)}
              onDrop={board.onColumnDrop(col.id)}
            />
          ))}
        </div>
      </Page>
      <Drawer open={open != null} onOpenChange={(next) => !next && setOpenId(null)}>
        <DrawerContent size="md">
          {open && (
            <>
              <DrawerHeader>
                <DrawerTitle>{open.title}</DrawerTitle>
                <DrawerDescription>{open.id}</DrawerDescription>
              </DrawerHeader>
              <DrawerBody>
                <Stack gap={5}>
                  <HStack gap={2} wrap>
                    <Badge tone={priorityTones[open.priority]}>{priorityLabels[open.priority]} priority</Badge>
                    {open.labels.map((l) => (
                      <Badge key={l} variant="outline">
                        {l}
                      </Badge>
                    ))}
                  </HStack>
                  <Text variant="supporting">{open.description}</Text>
                  <dl className="grid grid-cols-[7rem_1fr] items-center gap-x-4 gap-y-3 text-[13px]">
                    <dt className="text-muted-foreground">Status</dt>
                    <dd>
                      <SimpleSelect
                        aria-label="Status"
                        size="sm"
                        items={columns.map((c) => ({ value: c.id, label: c.title }))}
                        value={openAt?.column ?? null}
                        onValueChange={(v) => v && board.moveTo(open.id, v, board.state[v]?.length ?? 0)}
                        className="w-44"
                      />
                    </dd>
                    <dt className="text-muted-foreground">Assignee</dt>
                    <dd className="flex items-center gap-2 text-foreground">
                      <Avatar size="xs" name={open.assignee} aria-hidden />
                      {open.assignee}
                    </dd>
                    <dt className="text-muted-foreground">Due</dt>
                    <dd className="text-foreground">{open.due ? <Timestamp value={open.due} format="absolute" tooltip={false} dateOptions={{ dateStyle: 'medium' }} /> : 'No due date'}</dd>
                  </dl>
                </Stack>
              </DrawerBody>
            </>
          )}
        </DrawerContent>
      </Drawer>
    </ConsoleShell>
  );
}

import type { BadgeProps, BreadcrumbItem } from '@gntik-ai/ui';

export interface BoardColumn {
  id: string;
  title: string;
}

export interface BoardCard {
  id: string;
  title: string;
  description: string;
  assignee: string;
  labels: string[];
  priority: 'low' | 'medium' | 'high';
  /** ISO date. */
  due?: string;
}

/** Card ids per column id, in display order. */
export type BoardState = Record<string, string[]>;

export const priorityTones: Record<BoardCard['priority'], NonNullable<BadgeProps['tone']>> = { low: 'neutral', medium: 'info', high: 'warning' };
export const priorityLabels: Record<BoardCard['priority'], string> = { low: 'Low', medium: 'Medium', high: 'High' };

export const boardBreadcrumbs: BreadcrumbItem[] = [{ label: 'Acme Industries', href: '/overview' }, { label: 'Projects', href: '/projects' }, { label: 'Board' }];

export const boardColumns: BoardColumn[] = [
  { id: 'backlog', title: 'Backlog' },
  { id: 'in-progress', title: 'In progress' },
  { id: 'review', title: 'In review' },
  { id: 'done', title: 'Done' },
];

export const boardCards: BoardCard[] = [
  { id: 'T-101', title: 'Rotate staging database credentials', description: 'Move the staging credentials to the secrets store and rotate them.', assignee: 'Ada Example', labels: ['security'], priority: 'high', due: '2026-10-08' },
  { id: 'T-102', title: 'Add retry budget to webhooks', description: 'Cap retries per endpoint per hour so one bad endpoint cannot flood the queue.', assignee: 'Linus Park', labels: ['backend'], priority: 'medium' },
  { id: 'T-103', title: 'Empty state for the invoices table', description: 'Explain why the table is empty on new workspaces and link to billing settings.', assignee: 'Grace Hall', labels: ['frontend', 'design'], priority: 'low' },
  { id: 'T-104', title: 'Migrate usage exports to the new queue', description: 'Large exports should run as background jobs and notify when ready.', assignee: 'Ada Example', labels: ['backend'], priority: 'high', due: '2026-10-15' },
  { id: 'T-105', title: 'Keyboard shortcuts for the deployments table', description: 'J / K to move, Enter to open, X to select.', assignee: 'Grace Hall', labels: ['frontend', 'a11y'], priority: 'medium' },
  { id: 'T-106', title: 'Document the audit log export format', description: 'Fields, types and an example line for the JSON export.', assignee: 'Linus Park', labels: ['docs'], priority: 'low' },
  { id: 'T-107', title: 'Region picker on project creation', description: 'Default to the workspace region, warn about data residency.', assignee: 'Ada Example', labels: ['frontend'], priority: 'medium' },
];

export const boardState: BoardState = {
  backlog: ['T-101', 'T-102', 'T-103'],
  'in-progress': ['T-104', 'T-105'],
  review: ['T-106'],
  done: ['T-107'],
};

/** Moves a card to `toColumn` at `toIndex` (clamped); returns a new state. */
export function moveCard(state: BoardState, cardId: string, toColumn: string, toIndex: number): BoardState {
  const next: BoardState = {};
  for (const [col, ids] of Object.entries(state)) next[col] = ids.filter((id) => id !== cardId);
  const target = next[toColumn] ?? [];
  const index = Math.max(0, Math.min(toIndex, target.length));
  next[toColumn] = [...target.slice(0, index), cardId, ...target.slice(index)];
  return next;
}

/** Column id and index of a card. */
export function locate(state: BoardState, cardId: string): { column: string; index: number } | null {
  for (const [column, ids] of Object.entries(state)) {
    const index = ids.indexOf(cardId);
    if (index >= 0) return { column, index };
  }
  return null;
}

import { useRef, useState, type DragEvent, type KeyboardEvent } from 'react';
import { flushSync } from 'react-dom';
import { locate, moveCard, type BoardCard, type BoardColumn, type BoardState } from './data';

export interface UseBoardOptions {
  columns: readonly BoardColumn[];
  cards: readonly BoardCard[];
  initial: BoardState;
  onMove?: (cardId: string, toColumn: string, toIndex: number) => void;
}

interface Grab {
  id: string;
  origin: { column: string; index: number };
}

/**
 * Board state with both drag paths: pointer (HTML drag and drop onto a column or before a card)
 * and keyboard (Space picks up, arrows move, Space or Enter drops, Escape cancels). Every step is
 * announced through `announcement`, and focus follows the moved card.
 */
export function useBoard({ columns, cards, initial, onMove }: UseBoardOptions) {
  const [state, setState] = useState<BoardState>(initial);
  const [grab, setGrab] = useState<Grab | null>(null);
  const [dragging, setDragging] = useState<string | null>(null);
  const [dropColumn, setDropColumn] = useState<string | null>(null);
  const [announcement, setAnnouncement] = useState('');
  const buttons = useRef(new Map<string, HTMLButtonElement>());

  const titleOf = (id: string) => cards.find((c) => c.id === id)?.title ?? id;
  const columnTitle = (id: string) => columns.find((c) => c.id === id)?.title ?? id;
  const where = (s: BoardState, column: string, index: number) => `${columnTitle(column)}, position ${index + 1} of ${s[column]?.length ?? 0}`;

  const register = (id: string) => (el: HTMLButtonElement | null) => {
    if (el) buttons.current.set(id, el);
    else buttons.current.delete(id);
  };

  /** Moves synchronously so the remounted card can take focus right away. */
  const commit = (id: string, column: string, index: number) => {
    const next = moveCard(state, id, column, index);
    flushSync(() => setState(next));
    buttons.current.get(id)?.focus();
    return next;
  };

  const moveTo = (id: string, column: string, index: number, announce = true) => {
    const next = commit(id, column, index);
    const at = locate(next, id);
    if (at) {
      if (announce) setAnnouncement(`Dropped ${titleOf(id)} in ${where(next, at.column, at.index)}.`);
      onMove?.(id, at.column, at.index);
    }
  };

  const onCardKeyDown = (id: string) => (e: KeyboardEvent<HTMLButtonElement>) => {
    const at = locate(state, id);
    if (!at) return;
    const held = grab?.id === id;
    if (e.key === ' ' || (held && e.key === 'Enter')) {
      e.preventDefault();
      if (held) {
        setGrab(null);
        setAnnouncement(`Dropped ${titleOf(id)} in ${where(state, at.column, at.index)}.`);
        onMove?.(id, at.column, at.index);
      } else {
        setGrab({ id, origin: at });
        setAnnouncement(`Picked up ${titleOf(id)} in ${where(state, at.column, at.index)}. Use the arrow keys to move, Space to drop, Escape to cancel.`);
      }
      return;
    }
    if (!held) return;
    const colIndex = columns.findIndex((c) => c.id === at.column);
    let target: { column: string; index: number } | null = null;
    if (e.key === 'ArrowLeft' || e.key === 'ArrowRight') {
      const nextCol = columns[colIndex + (e.key === 'ArrowRight' ? 1 : -1)];
      if (nextCol) target = { column: nextCol.id, index: Math.min(at.index, state[nextCol.id]?.length ?? 0) };
    } else if (e.key === 'ArrowUp' || e.key === 'ArrowDown') {
      const index = at.index + (e.key === 'ArrowDown' ? 1 : -1);
      if (index >= 0 && index < (state[at.column]?.length ?? 0)) target = { column: at.column, index };
    } else if (e.key === 'Escape' && grab) {
      e.preventDefault();
      const next = commit(id, grab.origin.column, grab.origin.index);
      setGrab(null);
      setAnnouncement(`Cancelled. ${titleOf(id)} returned to ${where(next, grab.origin.column, grab.origin.index)}.`);
      return;
    }
    if (!target) return;
    e.preventDefault();
    const next = commit(id, target.column, target.index);
    const now = locate(next, id);
    if (now) setAnnouncement(`Moved to ${where(next, now.column, now.index)}.`);
  };

  /** Space activates buttons on keyup; cancel it so picking up does not open the card. */
  const onCardKeyUp = (e: KeyboardEvent<HTMLButtonElement>) => {
    if (e.key === ' ') e.preventDefault();
  };

  const onDragStart = (id: string) => (e: DragEvent<HTMLElement>) => {
    e.dataTransfer?.setData('text/plain', id);
    if (e.dataTransfer) e.dataTransfer.effectAllowed = 'move';
    setDragging(id);
  };
  const onDragEnd = () => {
    setDragging(null);
    setDropColumn(null);
  };
  const onColumnDragOver = (column: string) => (e: DragEvent<HTMLElement>) => {
    if (!dragging) return;
    e.preventDefault();
    if (dropColumn !== column) setDropColumn(column);
  };
  const onColumnDrop = (column: string) => (e: DragEvent<HTMLElement>) => {
    if (!dragging) return;
    e.preventDefault();
    const before = (e.target as HTMLElement).closest<HTMLElement>('[data-card-index]');
    const from = locate(state, dragging);
    let index = before ? Number(before.dataset.cardIndex) : (state[column]?.length ?? 0);
    // Dropping before a later card of the same column: the card leaves its slot first.
    if (from && from.column === column && from.index < index) index -= 1;
    const id = dragging;
    setDragging(null);
    setDropColumn(null);
    moveTo(id, column, index);
  };

  return {
    state,
    grabbedId: grab?.id ?? null,
    dragging,
    dropColumn,
    announcement,
    register,
    moveTo,
    onCardKeyDown,
    onCardKeyUp,
    onDragStart,
    onDragEnd,
    onColumnDragOver,
    onColumnDrop,
  };
}

import {
  AppSidebarFooter,
  AppSidebarHeader,
  AppSidebarNav,
  AppTopbar,
  type AppSidebarFooterProps,
  type AppSidebarHeaderProps,
  type AppTopbarProps,
} from '@gntik-ai/blocks';
import { SidebarLayout, type BreadcrumbItem, type NavGroup, type SidebarLayoutProps, type UserMenuUser, type Workspace } from '@gntik-ai/ui';
import type { ReactNode } from 'react';

export interface ConsoleShellProps
  extends Pick<AppSidebarHeaderProps, 'currentWorkspaceId' | 'onWorkspaceChange' | 'onCreateWorkspace'>,
    Pick<AppSidebarFooterProps, 'usage' | 'helpHref' | 'helpLabel' | 'userMenuItems' | 'onSignOut'>,
    Pick<SidebarLayoutProps, 'sidebarLabel' | 'collapseMode'> {
  /** Page content (usually a <Page>). */
  children: ReactNode;
  /** Sidebar navigation; defaults to the AppSidebar sample groups. */
  nav?: NavGroup[];
  /** Href of the current page, marks the active nav item. */
  currentHref?: string;
  breadcrumbs?: BreadcrumbItem[] | null;
  workspaces?: Workspace[] | null;
  user?: UserMenuUser | null;
  /** Extra AppTopbar props (environment, notifications, theme control…). */
  topbar?: Omit<AppTopbarProps, 'breadcrumbs' | 'user'>;
  /** localStorage key for the collapsed sidebar; `undefined` disables persistence. */
  storageKey?: string;
}

/**
 * The console frame shared by the templates: SidebarLayout with the AppSidebar header, nav and
 * footer, and the AppTopbar (breadcrumb, ⌘K search, notifications, theme, user menu).
 * Templates fill it with a Page; products swap the nav, workspaces, user, usage meter, help
 * link and user-menu items.
 */
export function ConsoleShell({
  children,
  nav,
  currentHref,
  breadcrumbs,
  workspaces,
  currentWorkspaceId,
  onWorkspaceChange,
  onCreateWorkspace,
  user,
  usage,
  helpHref,
  helpLabel,
  userMenuItems,
  onSignOut,
  topbar,
  storageKey,
  sidebarLabel,
  collapseMode,
}: ConsoleShellProps) {
  return (
    <SidebarLayout
      fullScreen
      storageKey={storageKey}
      sidebarLabel={sidebarLabel}
      collapseMode={collapseMode}
      sidebarHeader={({ collapsed }) => (
        <AppSidebarHeader
          collapsed={collapsed}
          workspaces={workspaces}
          currentWorkspaceId={currentWorkspaceId}
          onWorkspaceChange={onWorkspaceChange}
          onCreateWorkspace={onCreateWorkspace}
        />
      )}
      sidebar={({ collapsed }) => <AppSidebarNav groups={nav} currentHref={currentHref} collapsed={collapsed} />}
      sidebarFooter={({ collapsed }) => (
        <AppSidebarFooter
          collapsed={collapsed}
          user={user}
          usage={usage}
          helpHref={helpHref}
          helpLabel={helpLabel}
          userMenuItems={userMenuItems}
          onSignOut={onSignOut}
        />
      )}
      topbar={<AppTopbar breadcrumbs={breadcrumbs} user={user} {...topbar} />}
    >
      {children}
    </SidebarLayout>
  );
}
